// Generated by scripts/build_offline.mjs. Edit src modules instead.
'use strict';
const VOICE_AUDIO_FOLDERS = Object.freeze({
  am_echo: 'echo',
});

function normalizeVoiceId(voiceId) {
  return Object.hasOwn(VOICE_AUDIO_FOLDERS, voiceId) ? voiceId : 'am_echo';
}

function getVoiceAudioPath(questionId, voiceId = 'am_echo') {
  const folder = VOICE_AUDIO_FOLDERS[normalizeVoiceId(voiceId)];
  return `output/audio/${folder}/${encodeURIComponent(questionId)}.wav`;
}

const SETTINGS_KEY = 'sentence-trainer-speech-v1';
const voiceSelect = document.querySelector('#voice-select');
const rateInput = document.querySelector('#rate-input');
const rateValue = document.querySelector('#rate-value');
const repeatInput = document.querySelector('#repeat-input');
const pauseInput = document.querySelector('#pause-input');
const voiceNote = document.querySelector('#voice-note');
let previewAudio;

function loadSettings() {
  try { return JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}'); }
  catch { return {}; }
}

function saveSettings() {
  try {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify({
      voiceId: normalizeVoiceId(voiceSelect.value),
      rate: Number(rateInput.value),
      repeat: Number(repeatInput.value),
      pause: Number(pauseInput.value),
    }));
  } catch {
    voiceNote.textContent = '浏览器无法保存设置。';
  }
}

const saved = loadSettings();
voiceSelect.value = normalizeVoiceId(saved.voiceId);
rateInput.value = String(saved.rate ?? 0.85);
rateValue.value = `${Number(rateInput.value).toFixed(2).replace(/0$/, '').replace(/\.0$/, '')}×`;
repeatInput.value = String(saved.repeat ?? 1);
pauseInput.value = String(saved.pause ?? 0);
function voiceName() {
  return 'Echo';
}

function updatePreviewLabel() {
  voiceNote.textContent = `此页播放第 1 题的 Kokoro ${voiceName()} 实际录制音频。`;
}

updatePreviewLabel();

rateInput.addEventListener('input', () => {
  rateValue.value = `${Number(rateInput.value).toFixed(2).replace(/0$/, '').replace(/\.0$/, '')}×`;
  saveSettings();
});
for (const control of [repeatInput, pauseInput]) control.addEventListener('change', saveSettings);
voiceSelect.addEventListener('change', () => {
  saveSettings();
  updatePreviewLabel();
});

document.querySelector('#test-voice').addEventListener('click', () => {
  if (previewAudio) {
    previewAudio.pause();
    previewAudio.currentTime = 0;
  }
  const selectedVoice = normalizeVoiceId(voiceSelect.value);
  previewAudio = new Audio(new URL(getVoiceAudioPath('LM-001', selectedVoice), document.baseURI));
  previewAudio.playbackRate = Number(rateInput.value);
  previewAudio.onerror = () => { voiceNote.textContent = `${voiceName()} 音频播放失败，请重新点击试听。`; };
  previewAudio.play().then(() => {
    voiceNote.textContent = `正在播放 Kokoro ${voiceName()} 美式男声音频。`;
    saveSettings();
  }).catch(() => { voiceNote.textContent = `${voiceName()} 音频播放失败，请重新点击试听。`; });
});
